INSERT INTO sources (source_id, source_type, title, scope) VALUES
 ('SRC_BURKERT_PYTHAGOREANISM','secondary scholarship','Walter Burkert, Lore and Science in Ancient Pythagoreanism, trans. Edwin L. Minar (Harvard University Press, 1972; original German: Weisheit und Wissenschaft, 1962)','Greek'),
 ('SRC_DUDLEY_NUMEROLOGY','secondary scholarship','Underwood Dudley, Numerology: Or, What Pythagoras Wrought (Mathematical Association of America, 1997)','Theosophical'),
 ('SRC_JUICEWRLD_999_PITCHFORK','journalism','Pitchfork / Genius profiles of Juice WRLD''s ''999'' philosophy (inverting 666; the 999 Club) and its posthumous adoption by fans as a memorial and protective sign (2018-2020)','Contemporary Folklore & Vernacular Religion')
INSERT INTO _e VALUES
 ('ENT_GRK_PYTHAGOREAN_NUMBERS','Pythagorean Number Mysticism','Sacred-number doctrine','Greek number metaphysics','Greek','[''cosmic order'', ''number'', ''harmony'', ''divine principle'']','B','The Pythagorean doctrine that numbers are the divine archai (first principles) of reality (''all is number''); the tetractys as a sacred figure and the special sanctity of particular numbers, founding the Western tradition of sacred arithmetic. Pythagoras fl. c. 530 BCE.'),
 ('ENT_JM_GEMATRIA','Gematria','Number-hermeneutic practice','Kabbalistic number-hermeneutics','Jewish Mystical','[''exegesis'', ''number'', ''divine names'', ''angelology'']','B','The Kabbalistic technique in which Hebrew letters equal numerical values, so words sharing a sum share hidden meaning; numbers thereby carry divine and angelic significance. The ten sefirot are themselves the numerical emanations of the divine.'),
 ('ENT_REN_NUMBER_SCALE','The Scale of Numbers (Agrippa)','Esoteric correspondence system','Renaissance number-angel correspondence','Renaissance Esoteric','[''correspondence'', ''number'', ''angelology'', ''divine names'', ''cosmic hierarchy'']','B','In De occulta philosophia Book II, Agrippa tabulates each number 1-12 against its angels, divine names, planetary and cosmic ranks (the Scales of the numbers). This is the explicit number-to-angel bridge that joins ancient number mysticism to angelology.'),
 ('ENT_MOD_NUMEROLOGY','Modern Numerology','Divinatory system','Modern occult number divination','Theosophical','[''divination'', ''number'', ''self-knowledge'', ''destiny'']','B','The late-19th and 20th-century revival of Pythagorean number meaning (life-path and destiny numbers, the spiritual significance of repeating digits), popularized through Theosophical and New Thought milieus.'),
 ('ENT_VF_999','999 (Juice WRLD)','Cultural number-devotion','Vernacular number-devotion','Contemporary Folklore & Vernacular Religion','[''memorial'', ''protection'', ''transformation'', ''self-empowerment'']','B','Rapper Juice WRLD''s ''999'' creed: the inversion of 666, turning pain and negativity into something good and rising above. After his death (Dec 2019) fans use 999 (and the 999 Club) as a devotional, memorial and apotropaic sign. Included because fans genuinely use it as a mantra/protective sign, not as fiction.'),
 ('ENT_VF_ELEVEN_ELEVEN','11:11','Cultural number-devotion','Vernacular number-devotion','Contemporary Folklore & Vernacular Religion','[''synchronicity'', ''wish-making'', ''angelic sign'', ''guidance'']','B','The widespread make-a-wish / synchronicity practice of noticing the time 11:11, read as an angelic or ''the Universe'' sign of alignment - a digital-age angel-number devotion.');
