INSERT INTO entity_sources (entity_id,source_id,evidence_type,source_note)
INSERT INTO _p VALUES
 ('ENT_GRK_PYTHAGOREAN_NUMBERS','PER_GRK_ARCHAIC','The Pythagorean doctrine that numbers are the divine archai (first principles) of reality (''all is number''); the tetractys as a sacred figure and the special sanctity of particular numbers, founding the Western tradition of sacred arithmetic. Pythagoras fl. c. 530 BCE.'),
 ('ENT_JM_GEMATRIA','PER_JM_MEDIEVAL','The Kabbalistic technique in which Hebrew letters equal numerical values, so words sharing a sum share hidden meaning; numbers thereby carry divine and angelic significance. The ten sefirot are themselves the numerical emanations of the divine.'),
 ('ENT_REN_NUMBER_SCALE','PER_RENAISSANCE','In De occulta philosophia Book II, Agrippa tabulates each number 1-12 against its angels, divine names, planetary and cosmic ranks (the Scales of the numbers). This is the explicit number-to-angel bridge that joins ancient number mysticism to angelology.'),
 ('ENT_MOD_NUMEROLOGY','PER_MODERN_OCCULT','The late-19th and 20th-century revival of Pythagorean number meaning (life-path and destiny numbers, the spiritual significance of repeating digits), popularized through Theosophical and New Thought milieus.'),
 ('ENT_VF_999','PER_DIGITAL_FOLKLORE','Rapper Juice WRLD''s ''999'' creed: the inversion of 666, turning pain and negativity into something good and rising above. After his death (Dec 2019) fans use 999 (and the 999 Club) as a devotional, memorial and apotropaic sign. Included because fans genuinely use it as a mantra/protective sign, not as fiction.'),
 ('ENT_VF_ELEVEN_ELEVEN','PER_DIGITAL_FOLKLORE','The widespread make-a-wish / synchronicity practice of noticing the time 11:11, read as an angelic or ''the Universe'' sign of alignment - a digital-age angel-number devotion.');
INSERT INTO entity_periods (entity_id,period_id,confidence,rationale,source_id,review_status)
INSERT INTO _r VALUES
 ('ENT_ISR_GABRIEL','reception_of','ENT_ZOR_AMESHA_SPENTAS','medium','The Second-Temple Jewish archangel heptad, of which Gabriel is a member, was shaped on the model of the Zoroastrian Amesha Spentas during and after Persian-period contact (Boyce).'),
 ('ENT_ISR_RAPHAEL','reception_of','ENT_ZOR_AMESHA_SPENTAS','medium','Raphael, named among the seven archangels (Tobit, 1 Enoch), belongs to the post-exilic archangelic heptad patterned after the Amesha Spentas following Achaemenid contact (Boyce).'),
 ('ENT_ISR_URIEL','reception_of','ENT_ZOR_AMESHA_SPENTAS','medium','Uriel, one of the seven archangels of 1 Enoch, is part of the Second-Temple heptad of holy ones modeled on the Zoroastrian Amesha Spentas after Persian-period influence (Boyce).'),
 ('ENT_CHR_GUARDIAN_ANGELS','reception_of','ENT_ZOR_FRAVASHIS','medium','The Christian notion of a personal guardian angel assigned to each soul descends, via Second-Temple Judaism, from the Zoroastrian fravashi - the personal protective spirit-prototype (Boyce).'),
 ('ENT_JM_GEMATRIA','aligned_with','ENT_GRK_PYTHAGOREAN_NUMBERS','medium','Gematria and Pythagorean number mysticism are parallel ancient doctrines treating number as a carrier of hidden divine meaning; their later confluence underlies Renaissance number magic (Scholem; Burkert).'),
 ('ENT_JM_GEMATRIA','aligned_with','ENT_JM_SEFIROT','high','The sefirot ARE the ten numerical emanations of Kabbalah (sefirah = ''number/counting''); gematria operates on the same premise that number is divine, so the two are intrinsically aligned (Scholem).'),
 ('ENT_REN_NUMBER_SCALE','reception_of','ENT_GRK_PYTHAGOREAN_NUMBERS','high','Agrippa''s Scale of Numbers (De occulta philosophia II) explicitly revives Pythagorean number doctrine, assigning metaphysical meaning to the numbers 1-12.'),
 ('ENT_REN_NUMBER_SCALE','reception_of','ENT_JM_GEMATRIA','high','Agrippa draws his number-to-divine-name correspondences from Kabbalistic gematria, integrating Hebrew letter-number values and the sefirot into the Scale of Numbers.'),
 ('ENT_MOD_NUMEROLOGY','reception_of','ENT_GRK_PYTHAGOREAN_NUMBERS','high','Modern numerology is explicitly framed as a revival of Pythagorean number meaning - the very title of the standard critical study calls it ''what Pythagoras wrought'' (Dudley).'),
 ('ENT_MOD_NUMEROLOGY','reception_of','ENT_REN_NUMBER_SCALE','medium','Modern numerology inherits its number-symbol correspondences through the Renaissance esoteric tradition (Agrippa''s Scales) as transmitted into 19th-century occult and Theosophical circles.'),
 ('ENT_VF_ANGEL_NUMBERS','reception_of','ENT_MOD_NUMEROLOGY','high','Angel numbers are the number-side inheritance: the New Age practice of reading repeating digits applies modern numerology''s symbolic number meanings to everyday synchronicities.'),
 ('ENT_VF_ANGEL_NUMBERS','reception_of','ENT_VF_NEWAGE_ANGELS','high','Angel numbers are the angel-side inheritance: the repeating digits are read as messages from one''s New Age guardian angels, fusing angelology with numerology (existing aligned_with/member_of edges record the same link from a different angle).'),
 ('ENT_VF_999','reception_of','ENT_VF_ANGEL_NUMBERS','medium','Juice WRLD''s devotional ''999'' sits within the angel-number culture of reading repeated digits as spiritually significant; fans treat 999 as a meaningful number-sign in exactly that idiom.'),
 ('ENT_VF_ELEVEN_ELEVEN','reception_of','ENT_VF_ANGEL_NUMBERS','high','11:11 is a flagship case of angel-number practice - a repeating-digit time read as an angelic or ''Universe'' sign to make a wish or note synchronicity.'),
 ('ENT_VF_999','aligned_with','ENT_VF_ELEVEN_ELEVEN','medium','Both are contemporary vernacular number-devotions in which a specific repeating digit is invested with protective, synchronistic or wish-granting power.'),
 ('ENT_REN_NUMBER_SCALE','aligned_with','ENT_ANGELS','medium','Agrippa''s Scale of Numbers tabulates each number against orders of angels, making it the explicit number-to-angel bridge linking the number-mysticism thread to the angelic hierarchy.');
